import{_ as t,o,c as d,a3 as a}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"Tenant API v1 — Payroll","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Tenant API v1 — Payroll | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/api/tenant-v1-payroll"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Tenant API v1 — Payroll | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/api/tenant-v1-payroll"}]]},"headers":[],"relativePath":"api/tenant-v1-payroll.md","filePath":"api/tenant-v1-payroll.md","lastUpdated":1786218247000}'),r={name:"api/tenant-v1-payroll.md"};function c(n,e,p,l,s,i){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="tenant-api-v1-—-payroll" tabindex="-1">Tenant API v1 — Payroll <a class="header-anchor" href="#tenant-api-v1-—-payroll" aria-label="Permalink to &quot;Tenant API v1 — Payroll&quot;">​</a></h1><p>Base path: <code>/api/tenant/v1</code></p><p>Middleware: <code>auth:tenant-api</code>, <code>tenant.user</code>, <code>not.suspended</code>, <code>verified</code>, <code>module:payroll</code>, plus <code>can:payroll.*</code>.</p><h2 id="payroll-profiles" tabindex="-1">Payroll profiles <a class="header-anchor" href="#payroll-profiles" aria-label="Permalink to &quot;Payroll profiles&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Permission</th></tr></thead><tbody><tr><td>GET</td><td><code>/payroll-profiles</code></td><td><code>payroll.view</code></td></tr><tr><td>POST</td><td><code>/payroll-profiles</code></td><td><code>payroll.create</code></td></tr><tr><td>GET</td><td><code>/payroll-profiles/{payrollProfile}</code></td><td><code>payroll.view</code></td></tr><tr><td>PUT</td><td><code>/payroll-profiles/{payrollProfile}</code></td><td><code>payroll.update</code></td></tr><tr><td>DELETE</td><td><code>/payroll-profiles/{payrollProfile}</code></td><td><code>payroll.delete</code></td></tr><tr><td>POST</td><td><code>/payroll-profiles/{payrollProfile}/restore</code></td><td><code>payroll.restore</code></td></tr><tr><td>DELETE</td><td><code>/payroll-profiles/{payrollProfile}/force</code></td><td><code>payroll.force.delete</code></td></tr></tbody></table><p>Create body: <code>employee_id</code> (required, unique per tenant), <code>base_salary</code> (required), optional <code>currency</code> (3 chars, default <code>USD</code>), <code>pay_frequency</code> (<code>monthly</code>|<code>biweekly</code>|<code>weekly</code>), <code>effective_from</code>, <code>notes</code>.</p><h2 id="pay-runs" tabindex="-1">Pay runs <a class="header-anchor" href="#pay-runs" aria-label="Permalink to &quot;Pay runs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Permission</th></tr></thead><tbody><tr><td>GET</td><td><code>/pay-runs</code></td><td><code>payroll.view</code></td></tr><tr><td>POST</td><td><code>/pay-runs</code></td><td><code>payroll.create</code></td></tr><tr><td>GET</td><td><code>/pay-runs/{payRun}</code></td><td><code>payroll.view</code></td></tr><tr><td>PUT</td><td><code>/pay-runs/{payRun}</code></td><td><code>payroll.update</code></td></tr><tr><td>POST</td><td><code>/pay-runs/{payRun}/approve</code></td><td><code>payroll.approve</code></td></tr><tr><td>POST</td><td><code>/pay-runs/{payRun}/pay</code></td><td><code>payroll.pay</code></td></tr><tr><td>POST</td><td><code>/pay-runs/{payRun}/post</code></td><td><code>payroll.post</code></td></tr><tr><td>DELETE</td><td><code>/pay-runs/{payRun}</code></td><td><code>payroll.delete</code></td></tr><tr><td>POST</td><td><code>/pay-runs/{payRun}/restore</code></td><td><code>payroll.restore</code></td></tr><tr><td>DELETE</td><td><code>/pay-runs/{payRun}/force</code></td><td><code>payroll.force.delete</code></td></tr></tbody></table><h3 id="post-pay-runs" tabindex="-1">POST <code>/pay-runs</code> <a class="header-anchor" href="#post-pay-runs" aria-label="Permalink to &quot;POST `/pay-runs`&quot;">​</a></h3><p>Body: <code>period_start</code>, <code>period_end</code> (required), optional <code>notes</code>.</p><p>Creates a draft pay run and one line per <strong>active</strong> employee with a payroll profile. Gross starts as <code>base_salary</code>; adjustments deduct unpaid leave and unexcused absences when Leave Management / Attendance are installed. Line payload includes <code>working_days</code>, <code>unpaid_leave_days</code>, <code>absent_days</code>, <code>days_present</code>, <code>gross</code>, <code>adjustments</code>, <code>net</code>.</p><h3 id="put-pay-runs-payrun" tabindex="-1">PUT <code>/pay-runs/{payRun}</code> <a class="header-anchor" href="#put-pay-runs-payrun" aria-label="Permalink to &quot;PUT `/pay-runs/{payRun}`&quot;">​</a></h3><p>Draft only. Optional <code>period_start</code>, <code>period_end</code>, <code>notes</code>, and <code>lines[]</code> with <code>id</code> plus optional <code>gross</code>, <code>adjustments</code>, <code>notes</code>. Net is recalculated as <code>gross + adjustments</code>.</p><h3 id="post-pay-runs-payrun-approve" tabindex="-1">POST <code>/pay-runs/{payRun}/approve</code> <a class="header-anchor" href="#post-pay-runs-payrun-approve" aria-label="Permalink to &quot;POST `/pay-runs/{payRun}/approve`&quot;">​</a></h3><p>Requires at least one line. <code>draft → approved</code>.</p><h3 id="post-pay-runs-payrun-pay" tabindex="-1">POST <code>/pay-runs/{payRun}/pay</code> <a class="header-anchor" href="#post-pay-runs-payrun-pay" aria-label="Permalink to &quot;POST `/pay-runs/{payRun}/pay`&quot;">​</a></h3><p><code>approved → paid</code>. Sets <code>paid_at</code>.</p><h3 id="post-pay-runs-payrun-post" tabindex="-1">POST <code>/pay-runs/{payRun}/post</code> <a class="header-anchor" href="#post-pay-runs-payrun-post" aria-label="Permalink to &quot;POST `/pay-runs/{payRun}/post`&quot;">​</a></h3><p>Soft Accounting integration. Body optional: <code>debit_account_id</code>, <code>credit_account_id</code>.</p><p>Requires Accounting entitled; pay run status <code>approved</code> or <code>paid</code>; net total &gt; 0; not already posted. Creates a <strong>draft</strong> journal (expense debit / liability credit) and stores <code>journal_entry_id</code>. Defaults to the first active expense and liability accounts when ids are omitted.</p>',20)])])}const h=t(r,[["render",c]]);export{u as __pageData,h as default};
